import {modelMetadata,modelSections} from './model-paper-data.js';
import {modelPreparation,modelVocabulary} from './model-paper-preparation.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sound=text=>`<button class="sound" data-speak="${esc(text)}" aria-label="Listen to ${esc(text)}">▷</button>`;
export const modelItems=modelSections.flatMap(s=>s.parts.flatMap(p=>p.items));
const byId=new Map(modelItems.map(item=>[item.id,item]));
const key='wortreise-model-paper-v1';
let root,state={auto:{},drafts:{},checks:{}},allShown=false;
function read(){try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&typeof saved==='object')state={auto:saved.auto||{},drafts:saved.drafts||{},checks:saved.checks||{}};}catch{}}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{message('This browser could not save the practice. You can still work through the paper.');}}
function message(text){if(root)root.querySelector('#paper-message').textContent=text;}
function normalized(text,strict=false){const value=String(text??'').normalize('NFC').trim().replace(/[.,!?;:]/g,'').replace(/\s+/g,' ');return strict?value:value.toLocaleLowerCase('de');}
export function gradeModelAnswer(item,values){return item.kind==='auto'&&values.length===item.answers.length&&item.answers.every((choices,i)=>choices.some(choice=>normalized(choice,item.caseSensitive)===normalized(values[i],item.caseSensitive)));}
export function modelProgress(saved){return {correct:modelItems.filter(i=>i.kind==='auto'&&saved.auto?.[i.id]?.status==='correct').length,reviewed:modelItems.filter(i=>i.kind==='writing'&&saved.drafts?.[i.id]?.trim()&&i.requirements.every((_,n)=>saved.checks?.[i.id]?.[n])).length};}
function source(page){return `<a class="exam-source" href="${modelMetadata.pdf}#page=${page}" target="_blank" rel="noopener">Model paper · p. ${page} ↗</a>`;}
function lines(item){return item.lines.map(line=>`${line.speaker?line.speaker+': ':''}${line.de}`).join('\n');}
function answer(item){return `<details class="paper-answer"><summary>${item.kind==='auto'?'Worked answer and explanation':'View model response and English meaning'}</summary><div class="paper-answer-body">${item.kind==='auto'?`<div class="paper-answer-line">${sound(item.model)}<strong lang="de">${esc(item.model)}</strong></div><p class="paper-translation">${esc(item.en)}</p>`:`<div class="paper-model-lines">${item.lines.map(line=>`<div><div class="paper-answer-line">${sound(line.de)}<span lang="de">${line.speaker?`<b>${esc(line.speaker)}:</b> `:''}${esc(line.de)}</span></div><p class="paper-translation">${esc(line.en)}</p></div>`).join('')}</div><button class="pill" data-paper-copy="${item.id}">Copy this model response</button>`}<p class="paper-reason">${esc(item.reason)}</p>${item.note?`<p class="paper-answer-note">${esc(item.note)}</p>`:''}</div></details>`;}
function itemCard(item){const previous=state.auto[item.id];return `<article class="paper-item" data-paper-item="${item.id}"><div class="paper-item-top"><span class="exam-chip">${esc(item.label)}</span>${source(item.page)}</div><h4>${esc(item.prompt)}</h4>${item.kind==='auto'?`<div class="exam-answer-fields">${item.answers.map((_,n)=>`<label>${item.answers.length>1?'Blank '+(n+1):'Your German answer'}<input id="paper-${item.id}-${n}" data-paper-input="${item.id}" data-paper-blank="${n}" autocomplete="off" spellcheck="false" lang="de" maxlength="600" value="${esc(previous?.values?.[n]||'')}"></label>`).join('')}</div><div class="paper-tools"><button class="btn small-btn" data-paper-check="${item.id}">Check answer</button>${specialKeys(item.id)}</div><p id="paper-feedback-${item.id}" class="paper-feedback ${previous?.status==='incorrect'?'is-error':''}" role="status">${previous?.status==='correct'?'✓ Matches a worked answer.':previous?.status==='incorrect'?'No model match yet. Compare the worked answer and explanation.':''}</p>`:`<label class="paper-draft-label" for="paper-draft-${item.id}">Your own German response<textarea id="paper-draft-${item.id}" data-paper-draft="${item.id}" lang="de" spellcheck="false" maxlength="10000" placeholder="Draft your response here, then compare it with the model…">${esc(state.drafts[item.id]||'')}</textarea></label>${specialKeys(item.id)}<fieldset class="paper-checklist"><legend>Self-review against the paper’s requirements</legend>${item.requirements.map((requirement,n)=>`<label><input type="checkbox" data-paper-criterion="${item.id}" data-paper-index="${n}" ${state.checks[item.id]?.[n]?'checked':''}>${esc(requirement)}</label>`).join('')}</fieldset>`}${answer(item)}</article>`;}
function specialKeys(id){return `<div class="exam-special-keys">${['ä','ö','ü','ß','Ä','Ö','Ü'].map(c=>`<button aria-label="Insert ${c} in this response" data-paper-key="${c}" data-paper-for="${id}">${c}</button>`).join('')}</div>`;}
function preparation(){return `<details class="paper-preparation"><summary>Extra skills this model paper tests <span>Possessives · new modals · writing</span></summary><div class="paper-prep-body">${modelPreparation.map(guide=>`<article><h3>${esc(guide.title)}</h3><p>${esc(guide.body)}</p><div class="exam-table-wrap" tabindex="0" role="region" aria-label="${esc(guide.title)}"><table><thead><tr>${guide.head.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${guide.rows.map(row=>`<tr>${row.map((cell,i)=>i?`<td>${esc(cell)}</td>`:`<th scope="row">${esc(cell)}</th>`).join('')}</tr>`).join('')}</tbody></table></div>${guide.examples.map(([de,en])=>`<div class="paper-prep-example">${sound(de)}<div><strong lang="de">${esc(de)}</strong><p>${esc(en)}</p></div></div>`).join('')}</article>`).join('')}<h3>Job, shopping and travel vocabulary in the paper</h3><div class="paper-vocabulary">${modelVocabulary.map(([de,en])=>`<div>${sound(de)}<strong lang="de">${esc(de)}</strong><span>${esc(en)}</span></div>`).join('')}</div></div></details>`;}
export function modelPaperSection(){read();return `<div class="paper-header"><span class="exam-badge">THE UPLOADED MODEL PAPER · FULLY WORKED</span><h2>Practise the paper.<br>Understand every answer.</h2><p>All six questions, case studies and sub-parts from your term-end model question paper, with German answers, English explanations and writing models.</p><div class="paper-metadata"><span><strong>180</strong> minutes</span><span><strong>90</strong> marks</span><span><strong>6</strong> main questions</span><span><strong>5</strong> PDF pages</span></div><div class="paper-tools"><a class="btn small-btn" href="${modelMetadata.pdf}" target="_blank" rel="noopener">Open original paper ↗</a><button class="pill" data-paper-download>Download worked answer guide</button><button class="pill" data-paper-share>Copy model paper link</button></div></div><div class="paper-answer-note"><strong>About these answers</strong><p>The PDF contains questions and no official answer key. These worked answers are prepared for revision. Writing models are examples; other correct responses can meet the same requirements. Grammar checks compare against listed answers, not an official marking scheme.</p></div><details class="paper-instructions"><summary>Paper instructions and mark allocation</summary><ol>${modelMetadata.instructions.map(instruction=>`<li>${esc(instruction)}</li>`).join('')}</ol></details>${preparation()}<div class="paper-toolbar"><div><strong id="paper-progress"></strong><small>Grammar matches and writing self-review are separate from the 307 ZIP exercises.</small></div><button class="pill" data-paper-show-all>Show all worked answers</button></div><p id="paper-message" role="status" aria-live="polite"></p><div class="paper-jump" aria-label="Model paper questions">${modelSections.map(s=>`<button class="pill" data-paper-open="${s.id}">${s.id.toUpperCase()} · ${s.marks} marks</button>`).join('')}</div><div class="paper-sections">${modelSections.map((section,n)=>`<details class="paper-question" id="paper-section-${section.id}" ${n===0?'open':''}><summary><span class="exam-guide-number">${section.id.toUpperCase()}</span><span><strong>${esc(section.title)}</strong><small>${esc(section.de)} · ${section.co} · ${section.marks} marks</small></span><span class="exam-expand" aria-hidden="true">+</span></summary><div class="paper-question-body">${section.scenario?`<details class="paper-scenario"><summary>Read the case study in German and English</summary><p lang="de">${esc(section.scenario)}</p><p class="paper-translation">${esc(section.scenarioEn)}</p>${source(section.page)}</details>`:''}${section.parts.map(part=>`<section class="paper-part" aria-labelledby="paper-heading-${part.id}"><div class="paper-part-heading"><h3 id="paper-heading-${part.id}">${esc(part.title)}</h3>${part.marks?`<span class="exam-chip">${part.marks} marks</span>`:''}</div><p class="paper-task-instruction">${esc(part.instruction)}</p>${part.items.map(itemCard).join('')}</section>`).join('')}</div></details>`).join('')}</div>`;}
export function workedAnswerGuide(){let text=`${modelMetadata.title}\nSource: ${modelMetadata.fileName}\n180 minutes | 90 marks | 6 main questions\n\nWorked answers for revision; no official answer key was supplied. Other valid writing answers are possible.\n\n`;for(const s of modelSections){text+=`${s.id.toUpperCase()}. ${s.title} (${s.marks} marks)\n${s.scenario?'Case study: '+s.scenario+'\n\n':''}`;for(const p of s.parts){text+=`\n${p.title}${p.marks?' ('+p.marks+' marks)':''}\n${p.instruction}\n`;for(const item of p.items){text+=`\n${item.label}. ${item.prompt}\nSource page: ${item.page}\nAnswer:\n${item.kind==='auto'?item.model:lines(item)}\n\nEnglish: ${item.kind==='auto'?item.en:item.lines.map(line=>line.en).join(' ')}\nWhy: ${item.reason}\n${item.note?'Note: '+item.note+'\n':''}${item.kind==='writing'?'Self-check: '+item.requirements.join('; ')+'\n':''}`;}}text+='\n';}return text;}
function updateProgress(){const p=modelProgress(state);root.querySelector('#paper-progress').textContent=`${p.correct} / 40 grammar items matched · ${p.reviewed} / 14 writing tasks self-reviewed`;}
function itemValues(item){return item.answers.map((_,n)=>root.querySelector(`#paper-${item.id}-${n}`).value);}
function check(item){const values=itemValues(item),feedback=root.querySelector('#paper-feedback-'+item.id);if(values.some(v=>!v.trim())){feedback.textContent='Fill each answer box first.';feedback.classList.add('is-error');return;}const correct=gradeModelAnswer(item,values);state.auto[item.id]={values,status:correct?'correct':'incorrect'};feedback.textContent=correct?'✓ Matches a worked answer.':'No model match yet. Compare the worked answer and explanation; other grammatical word orders may also be valid.';feedback.classList.toggle('is-error',!correct);persist();updateProgress();}
export function mountModelPaper(){root=document.querySelector('#exam-model');if(!root)return;updateProgress();let activeInput;
 root.addEventListener('focusin',e=>{if(e.target.matches('input[data-paper-input],textarea[data-paper-draft]'))activeInput=e.target;});
 root.addEventListener('input',e=>{if(e.target.dataset.paperInput){const id=e.target.dataset.paperInput;state.auto[id]={values:itemValues(byId.get(id)),status:'pending'};root.querySelector('#paper-feedback-'+id).textContent='';persist();updateProgress();}if(e.target.dataset.paperDraft){state.drafts[e.target.dataset.paperDraft]=e.target.value;persist();updateProgress();}});
 root.addEventListener('change',e=>{if(e.target.dataset.paperCriterion){const id=e.target.dataset.paperCriterion,index=Number(e.target.dataset.paperIndex);if(e.target.checked&&!state.drafts[id]?.trim()){e.target.checked=false;message('Write your response first, then use the checklist to review it.');return;}state.checks[id]??=[];state.checks[id][index]=e.target.checked;persist();updateProgress();}});
 root.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.paperInput){e.preventDefault();check(byId.get(e.target.dataset.paperInput));}});
 root.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;const d=button.dataset;
  if(d.paperCheck){check(byId.get(d.paperCheck));return;}
  if(d.paperOpen){const detail=root.querySelector('#paper-section-'+d.paperOpen);detail.open=true;detail.scrollIntoView({behavior:'instant',block:'start'});return;}
  if(d.paperShowAll!==undefined){allShown=!allShown;root.querySelectorAll('.paper-answer').forEach(detail=>detail.open=allShown);if(allShown)root.querySelectorAll('.paper-question').forEach(detail=>detail.open=true);button.textContent=allShown?'Hide worked answers':'Show all worked answers';return;}
  if(d.paperShare!==undefined||d.paperCopy){const text=d.paperCopy?lines(byId.get(d.paperCopy)):new URL('#exam-model',location.href).href;try{await navigator.clipboard.writeText(text);message(d.paperCopy?'Model response copied. Adapt it for your own answer.':'Model paper link copied.');}catch{message(d.paperCopy?'Copy the model text from the answer panel.':'Share this link: '+text);}return;}
  if(d.paperDownload!==undefined){const blob=new Blob([workedAnswerGuide()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Wortreise-German-model-paper-worked-answers.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Worked answer guide downloaded.');return;}
  if(d.paperKey){const card=button.closest('[data-paper-item]'),input=activeInput&&card.contains(activeInput)?activeInput:card.querySelector('input[data-paper-input],textarea[data-paper-draft]');const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(d.paperKey,start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();}
 });
}
